<?php session_start();?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuryer kabineti • Lavash N1</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;background:radial-gradient(circle at 15% 10%,#fff0e5,transparent 30%),#f6f7fb;color:#101828}.wrap{max-width:980px;margin:auto;padding:22px}.hero,.card{background:#fff;border:1px solid #e4e7ec;border-radius:24px;padding:22px;margin:14px 0;box-shadow:0 18px 55px #10182810}.hero{background:linear-gradient(135deg,#111827,#293548);color:#fff}.hero h1{margin:0}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.order{border:1px solid #eee;border-radius:18px;padding:16px;margin:11px 0;background:#fff}.muted{color:#667085}input,button{width:100%;padding:13px;border-radius:13px;border:1px solid #d0d5dd;margin:7px 0;font:inherit}button{background:linear-gradient(135deg,#ff4d00,#ff8a00);color:#fff;border:0;font-weight:900;cursor:pointer}.pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#dcfce7;font-weight:900}.mapbtn{display:inline-flex!important;width:auto!important;margin:4px 0!important;text-decoration:none;color:#fff;background:#111827;border-radius:12px;padding:10px 13px;font-weight:900}@media(max-width:700px){.grid{grid-template-columns:1fr}.wrap{padding:12px}}</style></head><body><div class="wrap"><div class="hero"><div style="font-size:38px">🛵</div><h1>Lavash N1 • Kuryer Pro</h1><p>Buyurtmani oling, xaritada manzilni oching va yo‘lga chiqing.</p></div><div class="card"><div id="app"></div></div></div><script>const api=(a,o={})=>fetch('courier_api.php?action='+a,o).then(r=>r.json()),A=document.querySelector('#app');async function boot(){let m=await api('me');if(!m.ok){A.innerHTML='<h2>🔐 Kuryer kirishi</h2><p class="muted">Bu kabinet faqat to‘g‘ridan-to‘g‘ri URL orqali ishlaydi.</p><form id="f"><input name="login" placeholder="Login: Daler" required><input name="password" placeholder="Parol: Lavash" type="password" required><button>Kirish</button></form>';f.onsubmit=async e=>{e.preventDefault();let d=await api('login',{method:'POST',body:new FormData(e.target)});d.ok?location.reload():alert(d.message)};return}A.innerHTML='<div class="grid"><div><h2>Salom, '+m.data.name+' 🟢</h2><span class="pill">ONLINE</span></div><div><button onclick="logout()">Chiqish</button></div></div><hr><h2>📦 Menga biriktirilgan buyurtmalar</h2><div id="orders">Yuklanmoqda...</div>';load()}async function load(){let d=await api('orders');document.querySelector('#orders').innerHTML=(d.data||[]).map(x=>{const m=(x.address||'').match(/GPS:\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)/i);const link=m?'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(m[1]+','+m[2]):null;return '<div class="order"><b>#'+x.id+' — '+x.customer_name+'</b><p>📞 '+x.phone+'<br>📍 '+(x.address||'')+'<br>💰 '+Number(x.amount).toLocaleString('uz-UZ')+' so‘m · '+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'</p>'+(link?'<a class="mapbtn" target="_blank" rel="noopener" href="'+link+'">🧭 Google Maps’da yo‘l</a>':'')+'<p class="muted">'+(x.note||'')+'</p><button onclick="st('+x.id+',\'delivering\')">🛵 Yo‘lda</button><button onclick="st('+x.id+',\'completed\')">✅ Yetkazildi</button></div>';}).join('')||'<p class="muted">Sizga biriktirilgan buyurtma yo‘q.</p>'}async function st(id,s){let f=new FormData();f.append('order_id',id);f.append('status',s);await api('status',{method:'POST',body:f});load()}async function logout(){await api('logout');location.reload()}boot();setInterval(load,6000)</script></body></html>